// ============================================
// ROUTE: Determine request type and validate JWT
// ============================================
const body = $input.item.json.body;

if (!body.jwt) {
  return [{ json: { error: 'Missing JWT token', valid: false, request_type: 'unknown' } }];
}

const request_type = body.request_type || 'generate';

// Validate based on request type
if (request_type === 'parse') {
  if (!body.fileData || !body.fileName || !body.fileType) {
    return [{ json: { error: 'Missing file data for parse request', valid: false, request_type } }];
  }
} else if (request_type === 'generate') {
  if (!body.resume_data) {
    return [{ json: { error: 'Missing resume_data for generate request', valid: false, request_type } }];
  }
}

try {
  // Decode Outseta JWT
  const jwt = body.jwt;
  const parts = jwt.split('.');

  // Base64 decode fix for some environments
  const base64Url = parts[1];
  const base64 = base64Url.replace(/-/g, '+').replace(/_/g, '/');
  const payload = JSON.parse(Buffer.from(base64, 'base64').toString());

  // Extract User & Plan Info (Outseta Custom Claims)
  // 'sub' is the User UID
  // 'outseta:planUid' is the Plan UID
  const userId = payload.sub; 
  const outsetaUid = payload.sub; // User UID for usage tracking
  const planUid = payload['outseta:planUid'];
  const accountUid = payload['outseta:accountUid'];

  // PLAN MAPPING
  // Map Outseta Plan UIDs to the tier names expected by the logic
  const planMap = {
     'zWZD0rQp': 'starter',
     'rQVqlLm6': 'pro',
     'NmdnNO90': 'elite',
     'rmk5Xk9g': 'agency',
     'L9nbKV9Z': 'free'
  };

  // Determine Tier
  let tier = 'free';
  if (planUid && planMap[planUid]) {
    tier = planMap[planUid];
  } else if (payload.Account?.SubscriptionPlan?.Uid) {
     // Fallback for legacy/standard structure if different
     const legacyUid = payload.Account.SubscriptionPlan.Uid.toLowerCase();
     if (legacyUid.includes('agency')) tier = 'agency';
     else if (legacyUid.includes('elite')) tier = 'elite';
     else if (legacyUid.includes('pro')) tier = 'pro';
     else if (legacyUid.includes('starter')) tier = 'starter';
  }

  return [{ 
    json: {
      valid: true,
      request_type: request_type,
      user_id: userId,
      outseta_uid: outsetaUid,
      account_uid: accountUid,
      plan_uid: planUid,
      tier: tier,
      // Parse fields
      fileData: body.fileData || null,
      fileName: body.fileName || null,
      fileType: body.fileType || null,
      fileSizeBytes: body.fileSizeBytes || 0,
      // Generate fields
      resume_data: body.resume_data || null
    }
  }];
} catch (error) {
  return [{ json: { error: 'Invalid JWT: ' + error.message, valid: false, request_type } }];
}

// ============================================
// EXTRACT TEXT FROM UPLOADED FILE
// Works in n8n cloud and self-hosted
// No external dependencies required
// ============================================
const data = $input.first().json;
const fileData = data.fileData;
const fileName = data.fileName;
const fileType = data.fileType;

console.log(`Processing file: ${fileName} (${fileType})`);

let extractedText = '';
let extractionMethod = '';

try {
  // Decode base64 to buffer
  const buffer = Buffer.from(fileData, 'base64');

  if (fileType === 'text/plain') {
    // ---- TXT: direct decode ----
    extractedText = buffer.toString('utf-8');
    extractionMethod = 'text';

  } else if (fileType === 'application/pdf') {
    // ---- PDF: extract text from PDF structure ----
    const pdfContent = buffer.toString('binary'); // Keep as binary string

    // Method 1: Standard PDF Text Extraction (Aggressive Regex)
    // Loops through all BT/ET (Begin Text / End Text) blocks
    // Captures text inside parens (...) or brackets [...]

    const textChunks = [];
    const blocks = pdfContent.match(/BT[\s\S]*?ET/g) || [];

    if (blocks.length > 0) {
      for (const block of blocks) {
        // Match standard text strings (e.g. (Hello World) Tj)
        // Also handling escaped parens \( \) inside the string
        const standardMatches = block.match(/\((?:[^(\\]|\\.)*\)\s*Tj/g) || [];
        for (const match of standardMatches) {
           const raw = match.replace(/\((.*)\)\s*Tj/, '$1');
           textChunks.push(raw);
        }

        // Match array text strings (e.g. [(Hello) -20 (World)] TJ)
        const arrayMatches = block.match(/\[((?:[^\]]|\\.)*)\]\s*TJ/g) || [];
        for (const match of arrayMatches) {
           const content = match.replace(/\[((.*))\]\s*TJ/, '$1');
           // Extract parts inside parens from the array
           const parts = content.match(/\((?:[^(\\]|\\.)*\)/g) || [];
           for (const p of parts) {
             textChunks.push(p.slice(1, -1));
           }
        }
      }
      extractionMethod = 'pdf-regex-structure';
    } 

    // Method 2: Raw content fallback (if structure extraction yields too little)
    // Some PDFs use compression streams (FlateDecode) for text, which we can't easily inflate 
    // without libraries. However, some have uncompressed text objects.

    if (textChunks.length < 5) {
        // Fallback: Look for any string-like patterns in the entire file
        // e.g. (Resume) (Experience)
        const rawMatches = pdfContent.match(/\(([A-Za-z0-9\s,.\-@]{4,})\)/g) || [];
        for (const m of rawMatches) {
            textChunks.push(m.slice(1, -1));
        }
        if (textChunks.length > 0) extractionMethod += '+fallback-raw';
    }

    // Clean up extracted chunks
    extractedText = textChunks
      .map(t => t
        .replace(/\\n/g, '\n')
        .replace(/\\r/g, '')
        .replace(/\\t/g, ' ')
        .replace(/\\\(/g, '(')
        .replace(/\\\)/g, ')')
        .replace(/\\\\/g, '\\')
      )
      .join(' ')
      .replace(/\s+/g, ' ')
      .trim();

  } else if (
    fileType === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document' ||
    fileType === 'application/msword'
  ) {
    // ---- DOCX: extract from ZIP using built-in zlib ----
    const zlib = require('zlib');

    let offset = 0;

    // Parse ZIP local file headers
    while (offset < buffer.length - 4) {
      if (buffer[offset] === 0x50 && buffer[offset+1] === 0x4B && 
          buffer[offset+2] === 0x03 && buffer[offset+3] === 0x04) {

        const compressionMethod = buffer.readUInt16LE(offset + 8);
        const compressedSize = buffer.readUInt32LE(offset + 18);
        const fileNameLength = buffer.readUInt16LE(offset + 26);
        const extraLength = buffer.readUInt16LE(offset + 28);
        const entryName = buffer.toString('utf-8', offset + 30, offset + 30 + fileNameLength);

        const dataStart = offset + 30 + fileNameLength + extraLength;
        const dataEnd = dataStart + compressedSize;

        if (entryName === 'word/document.xml' && dataEnd <= buffer.length) {
          const compressedData = buffer.slice(dataStart, dataEnd);
          let xmlContent;

          if (compressionMethod === 8) { // Deflated
            try {
              xmlContent = zlib.inflateRawSync(compressedData).toString('utf-8');
            } catch (e) {
               try { xmlContent = zlib.inflateSync(compressedData).toString('utf-8'); } catch (e2) {}
            }
          } else {
            xmlContent = compressedData.toString('utf-8');
          }

          if (xmlContent) {
            extractedText = xmlContent
              .replace(/<w:p[^>]*>/g, '\n')
              .replace(/<w:tab\/>/g, '\t')
              .replace(/<[^>]+>/g, '')
              .replace(/&amp;/g, '&')
              .replace(/&lt;/g, '<')
              .replace(/&gt;/g, '>')
              .replace(/&quot;/g, '"')
              .replace(/\n{3,}/g, '\n\n')
              .trim();
            extractionMethod = 'docx-zip';
            break;
          }
        }
        offset = dataEnd;
      } else {
        offset++;
      }
    }
  } 

} catch (error) {
  console.error('Extraction error:', error.message);
}

// ---- CRITICAL FALLBACK FOR PDF/DOCX PARSING FAILURES ----
// If the regex/zip parsing failed (common with optimized PDFs or weird DOCX),
// we return a special flag to tell the AI that it needs to accept "Raw Base64" 
// (or that we failed nicely). 
// Since we can't use libraries, if extractedText is still empty/short,
// we will try one last "Low Quality" ascii dump of the buffer.

if (extractedText.length < 50) {
    const buffer = Buffer.from(fileData, 'base64');
    // Sanitize to only printable ASCII + whitespace
    const rawDump = buffer.toString('utf-8').replace(/[^\x20-\x7E\n\r\t]/g, '');

    // Check if the raw dump looks like it has content (naive check)
    if (rawDump.length > 200) {
        extractedText = "WARNING: PDF/DOCX structure parsing failed. content extracted from raw stream:\n\n" + rawDump.slice(0, 15000); // Limit size
        extractionMethod += '+last-resort-raw-ascii';
    }
}

return [{
  json: {
    extraction_failed: extractedText.length < 20, // Only fail if practically empty
    extractedText: extractedText || "No text could be extracted.",
    extractionMethod: extractionMethod,
    fileName: fileName,
    fileType: fileType,
    textLength: extractedText.length,
    user_id: data.user_id,
    outseta_uid: data.outseta_uid,
    tier: data.tier
  }
}];

// ============================================
// BUILD PARSE PROMPT
// Pre-serializes the Groq API body to avoid
// n8n HTTP Request JSON escaping bugs
// ============================================
const data = $input.first().json;

const systemPrompt = "You are an expert resume parser and field services career advisor. You extract structured data from resumes and identify transferable skills for mortgage field services, property inspection, and property preservation roles. You always respond with valid JSON only. No markdown, no backticks, no explanation text.";

const userMessage = "RESUME TEXT (extracted from " + data.fileName + "):
---
" + data.extractedText + "
---

Analyze this resume and extract structured data. Return ONLY valid JSON with no markdown, no backticks, no explanation. The JSON must follow this exact structure:

{
  "contact": {
    "fullName": "string",
    "email": "string",
    "phone": "string",
    "city": "string",
    "state": "string",
    "zipCode": "string",
    "linkedin": "string or empty",
    "website": "string or empty"
  },
  "summary": "A 2-3 sentence professional summary rewritten for field services roles",
  "experience": [
    {
      "company": "string",
      "title": "string",
      "location": "string",
      "startDate": "YYYY-MM format",
      "endDate": "YYYY-MM format or empty if current",
      "current": true,
      "description": "string describing responsibilities",
      "bullets": ["achievement 1", "achievement 2"]
    }
  ],
  "education": [
    {
      "school": "string",
      "degree": "string",
      "field": "string",
      "graduationDate": "YYYY-MM format"
    }
  ],
  "certifications": [
    {
      "name": "string",
      "issuer": "string",
      "date": "YYYY-MM format"
    }
  ],
  "skills": ["skill1", "skill2"],
  "transferableSkills": ["skills that transfer to field services work"],
  "industryTermMappings": [
    {
      "original": "term from their resume",
      "fieldServices": "equivalent field services term"
    }
  ],
  "strengthAreas": ["areas where this candidate is strong for field services"],
  "improvementSuggestions": ["suggestions to strengthen their field services resume"]
}

IMPORTANT:
- Extract ALL contact info, work history, education, and certifications
- Identify transferable skills (driving, documentation, time management, customer service, compliance)
- Map experience terms to field services equivalents
- If resume shows inspection, real estate, property, or mortgage experience, highlight it
- Return ONLY the JSON object, no other text";

// Build the complete Groq request as a JS object
const groqBody = {
  model: "llama-3.3-70b-versatile",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userMessage }
  ],
  temperature: 0.3,
  max_tokens: 4000,
  response_format: { type: "json_object" }
};

// Stringify HERE — this is safe because JSON.stringify in a Code node
// handles all escaping perfectly. The HTTP Request node will send
// this string as-is without trying to parse it.
return [{
  json: {
    user_id: data.user_id,
    outseta_uid: data.outseta_uid,
    tier: data.tier,
    groq_body_string: JSON.stringify(groqBody)
  }
}];

// ============================================
// PREPARE PARSE RESPONSE
// Clean and return structured resume data
// ============================================
const groqResponse = $input.first().json;
const userData = $('Build Parse Prompt').first().json;

let parsedData;
try {
  const content = groqResponse.choices?.[0]?.message?.content || '{}';
  // Strip markdown code fences if present
  const cleaned = content.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsedData = JSON.parse(cleaned);
} catch (parseError) {
  console.error('JSON parse error:', parseError.message);
  // Return a minimal valid response so the frontend doesn't break
  parsedData = {
    contact: {},
    summary: '',
    experience: [],
    education: [],
    certifications: [],
    skills: [],
    transferableSkills: [],
    industryTermMappings: [],
    strengthAreas: ['Resume uploaded but AI parsing returned unexpected format'],
    improvementSuggestions: ['Please review and edit your information manually']
  };
}

// Ensure all required fields exist
const result = {
  contact: parsedData.contact || {},
  summary: parsedData.summary || '',
  experience: parsedData.experience || [],
  education: parsedData.education || [],
  certifications: parsedData.certifications || [],
  skills: parsedData.skills || [],
  transferableSkills: parsedData.transferableSkills || [],
  industryTermMappings: parsedData.industryTermMappings || [],
  strengthAreas: parsedData.strengthAreas || [],
  improvementSuggestions: parsedData.improvementSuggestions || [],
  tokens_used: groqResponse.usage?.total_tokens || 0
};

return [{
  json: {
    ...result,
    user_id: userData.user_id,
    outseta_uid: userData.outseta_uid,
    tier: userData.tier
  }
}];

// Tier limits for AI RESUME GENERATE
const limits = {
  free: 0,
  starter: 1,
  pro: 10,
  elite: 50,
  agency: 999999
};

const usageResponse = $input.first().json;
const callCount = parseInt(usageResponse.call_count || usageResponse.body?.call_count) || 0;

const userData = $('Validate & Decode JWT').first().json;
const tier = userData.tier;

const limit = limits[tier] || 0;
const allowed = callCount < limit;

return [{
  json: {
    user_id: userData.user_id,
    outseta_uid: userData.outseta_uid,
    tier: tier,
    resume_data: userData.resume_data,
    call_count: callCount,
    limit: limit,
    remaining: Math.max(0, limit - callCount),
    allowed: allowed
  }
}];

// ============================================
// BUILD RESUME PROMPT
// Pre-serializes the Groq API body to avoid
// n8n HTTP Request JSON escaping bugs
// ============================================
const data = $input.first().json;
const rd = data.resume_data;

const targetRoles = rd.target_roles.join(', ');

let experienceText = '';
if (rd.experience && rd.experience.length > 0) {
  experienceText = rd.experience.map(job => {
    return `Job Title: ${job.title}
Company: ${job.company}
Location: ${job.location || 'N/A'}
Dates: ${job.start_date} – ${job.end_date || 'Present'}
Description: ${job.description || 'No description provided'}`;
  }).join('

');
} else {
  experienceText = 'No prior work experience provided.';
}

let educationText = 'Not provided';
if (rd.education && rd.education.length > 0) {
  educationText = rd.education.map(edu => `${edu.degree} | ${edu.school} | ${edu.graduation_year || 'N/A'}`).join('
');
}

let certsText = 'None listed';
if (rd.certifications && rd.certifications.length > 0) {
  certsText = rd.certifications.map(cert => `${cert.name} | ${cert.issuing_org} | ${cert.date || 'N/A'}`).join('
');
}

const skillsText = rd.skills && rd.skills.length > 0 ? rd.skills.join(', ') : 'Not specified';
const equipmentText = rd.equipment && rd.equipment.length > 0 ? rd.equipment.join(', ') : 'Not specified';

let coverageText = 'Not specified';
if (rd.coverage) {
  const parts = [];
  if (rd.coverage.travel_distance) parts.push(`Travel Distance: ${rd.coverage.travel_distance} miles`);
  if (rd.coverage.counties) parts.push(`Counties: ${rd.coverage.counties}`);
  if (rd.coverage.vehicle_type) parts.push(`Vehicle: ${rd.coverage.vehicle_type}`);
  coverageText = parts.join('
');
}

let availabilityText = 'Not specified';
if (rd.availability && rd.availability.length > 0) {
  availabilityText = rd.availability.join(', ');
}

const userMessage = `TARGET ROLES:
${targetRoles}

CONTACT INFORMATION:
Name: ${rd.contact.name}
Email: ${rd.contact.email}
Phone: ${rd.contact.phone}
City: ${rd.contact.city || 'N/A'}
State: ${rd.contact.state || 'N/A'}
LinkedIn: ${rd.contact.linkedin || 'Not provided'}
Website: ${rd.contact.website || 'Not provided'}
Professional Summary: ${rd.contact.summary || 'Not provided'}

WORK EXPERIENCE:
${experienceText}

EDUCATION:
${educationText}

CERTIFICATIONS:
${certsText}

SELECTED SKILLS:
${skillsText}

EQUIPMENT OWNED:
${equipmentText}

SERVICE COVERAGE:
${coverageText}

AVAILABILITY:
${availabilityText}

Please generate a professional, ATS-optimized resume tailored for the selected target roles.`;

const systemPrompt = "You are an expert resume writer specializing in mortgage field services and property inspection roles. You create professional, ATS-optimized resumes for field service workers.

Your task:
1. Analyze the user's experience, target roles, and skills
2. Generate a modern, professional resume that emphasizes their qualifications for their selected target roles
3. Use industry-specific terminology and keywords
4. Highlight transferable skills and relevant experience
5. Incorporate their equipment ownership and service coverage as selling points

Format Requirements:
- Use clear section headers in ALL CAPS
- Start each bullet with strong action verbs
- Include quantifiable achievements where possible
- Optimize for ATS (Applicant Tracking Systems)
- Use mortgage services and property inspection industry terminology

Return the resume in this EXACT structure:

[CONTACT INFORMATION]
Name | Email | Phone | City, State
LinkedIn (if provided) | Website (if provided)

[PROFESSIONAL SUMMARY]
2-3 sentences highlighting experience and alignment with target roles.

[CORE COMPETENCIES]
8-12 competencies relevant to target roles.

[PROFESSIONAL EXPERIENCE]
Job Title | Company Name | City, State | Start Date – End Date
3-5 achievement-focused bullet points per position.

[EDUCATION]
Degree | School Name | Graduation Year

[CERTIFICATIONS & TRAINING]
Certification Name | Issuing Organization | Date

[TECHNICAL PROFICIENCIES & EQUIPMENT]
Equipment, software, coverage, and availability details.";

const groqBody = {
  model: "llama-3.3-70b-versatile",
  messages: [
    { role: "system", content: systemPrompt },
    { role: "user", content: userMessage }
  ],
  temperature: 0.7,
  max_tokens: 3000
};

return [{
  json: {
    user_id: data.user_id,
    outseta_uid: data.outseta_uid,
    tier: data.tier,
    remaining: data.remaining,
    groq_body_string: JSON.stringify(groqBody)
  }
}];

const groqResponse = $input.first().json;
const quotaData = $('Has Quota?').first().json;

return [{
  json: {
    user_id: quotaData.user_id,
    outseta_uid: quotaData.outseta_uid,
    tier: quotaData.tier,
    prompt_tokens: groqResponse.usage?.prompt_tokens || 0,
    completion_tokens: groqResponse.usage?.completion_tokens || 0,
    total_tokens: groqResponse.usage?.total_tokens || 0,
    model: groqResponse.model || 'llama-3.3-70b-versatile',
    resume_content: groqResponse.choices?.[0]?.message?.content || 'No resume generated',
    remaining: quotaData.remaining - 1
  }
}];

// Tier limits for AI RESUME PARSE
const limits = {
  free: 0,
  starter: 5,
  pro: 20,
  elite: 100,
  agency: 999999
};

const usageResponse = $input.first().json;
const callCount = parseInt(usageResponse.call_count || usageResponse.body?.call_count) || 0;

const userData = $('Validate & Decode JWT').first().json;
const tier = userData.tier;

const limit = limits[tier] || 0;
const allowed = callCount < limit;

return [{
  json: {
    ...$input.first().json,
    // Preserve previous data
    user_id: userData.user_id,
    outseta_uid: userData.outseta_uid,
    tier: tier,
    call_count: callCount,
    limit: limit,
    remaining: Math.max(0, limit - callCount),
    allowed: allowed
  }
}];
